def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = []

    # Locate each solid 3x3 square.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(
                grid[rr][cc] == color
                for rr in range(r, r + 3)
                for cc in range(c, c + 3)
            ):
                centers.append((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    horizontal = {}
    vertical = {}

    for r, c, color in centers:
        horizontal.setdefault(r, set()).add(color)
        vertical.setdefault(c, set()).add(color)

    for r, colors in horizontal.items():
        for c in range(w):
            out[r][c] = next(iter(colors)) if len(colors) == 1 else 0

    for c, colors in vertical.items():
        for r in range(h):
            # A crossing of differently colored lines is left blank.
            crossing = horizontal.get(r, set())
            if crossing and (len(crossing | colors) > 1):
                out[r][c] = 0
            else:
                out[r][c] = next(iter(colors)) if len(colors) == 1 else 0

    return out
